exercise.solution:
def ecarts_graines(base, variante):
    a={r['seed']:r['score'] for r in base};b={r['seed']:r['score'] for r in variante}
    if set(a)!=set(b) or not a:raise ValueError('graines non appariées')
    return [b[k]-a[k] for k in sorted(a)]

exercise.check:
a=[{'seed':1,'score':2},{'seed':2,'score':5}];b=[{'seed':2,'score':4},{'seed':1,'score':4}]
assert ecarts_graines(a,b)==[2,-1]
try:ecarts_graines(a,[{'seed':3,'score':4}])
except ValueError:pass
else:raise AssertionError('graines différentes acceptées')
